package com.picviewer.app;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;
import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
import com.picviewer.core.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class)
@org.robolectric.annotation.Config(sdk=34,qualifiers="w960dp-h600dp-land-mdpi")
@GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class LocalSourceTest {
 static final String TREE="content://test.picviewer.local/tree/root";MainActivity a;Fixture provider;
 static final class Node {String id,name,mime,parent;long modified=1;File file;Node(String i,String n,String m,String p){id=i;name=n;mime=m;parent=p;}}
 public static class Fixture extends ContentProvider {
  Map<String,Node> nodes=new LinkedHashMap<>();boolean denied=false,loading=false,error=false,nullQuery=false,unknownSize=false,mutate=false;int writes=0;List<String> modes=new ArrayList<>();
  public boolean onCreate(){return true;}
  public Cursor query(Uri uri,String[] projection,String selection,String[] args,String sort){if(denied)throw new SecurityException("revoked-fixture");if(nullQuery)return null;MatrixCursor c=new MatrixCursor(projection);List<String> segments=uri.getPathSegments();String id=DocumentsContract.getDocumentId(uri);boolean children=segments.get(segments.size()-1).equals("children");for(Node n:nodes.values())if(children?Objects.equals(n.parent,id):n.id.equals(id)){Object[] row=new Object[projection.length];for(int i=0;i<projection.length;i++)switch(projection[i]){case "document_id":row[i]=n.id;break;case "_display_name":row[i]=n.name;break;case "mime_type":row[i]=n.mime;break;case "_size":row[i]=unknownSize?null:n.file==null?0:n.file.length();break;case "last_modified":row[i]=n.modified;break;}c.addRow(row);}Bundle extra=new Bundle();extra.putBoolean(DocumentsContract.EXTRA_LOADING,loading);if(error)extra.putString(DocumentsContract.EXTRA_ERROR,"fixture-error");c.setExtras(extra);return c;}
  public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{if(denied)throw new SecurityException();modes.add(mode);if(!mode.equals("r")){writes++;throw new FileNotFoundException();}Node n=nodes.get(DocumentsContract.getDocumentId(uri));if(n==null||n.file==null)throw new FileNotFoundException();if(mutate)n.modified++;return ParcelFileDescriptor.open(n.file,ParcelFileDescriptor.MODE_READ_ONLY);}
  public String getType(Uri u){return "image/jpeg";}public Uri insert(Uri u,ContentValues v){writes++;throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] args){writes++;throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] args){writes++;throw new UnsupportedOperationException();}
 }
 @Before public void setup()throws Exception{a=Robolectric.buildActivity(MainActivity.class).setup().get();provider=new Fixture();android.content.pm.ProviderInfo info=new android.content.pm.ProviderInfo();info.authority="test.picviewer.local";provider.attachInfo(a,info);org.robolectric.shadows.ShadowContentResolver.registerProviderInternal("test.picviewer.local",provider);provider.nodes.put("root",new Node("root","시험 사진",DocumentsContract.Document.MIME_TYPE_DIR,null));provider.nodes.put("folder",new Node("folder","여행",DocumentsContract.Document.MIME_TYPE_DIR,"root"));add("jpeg","사진1.jpg","folder");add("png","사진2.png","root");}
 void add(String id,String name,String parent)throws Exception{Node n=new Node(id,name,"image/jpeg",parent);n.file=new File(a.getCacheDir(),id+".fixture");try(InputStream in=a.getAssets().open("demo/01-mountain.jpg");OutputStream out=new FileOutputStream(n.file)){byte[] b=new byte[8192];int count;while((count=in.read(b))!=-1)out.write(b,0,count);}provider.nodes.put(id,n);}
 @After public void done(){a.onDestroy();assertEquals(0,provider.writes);}
 Config config(){Config c=new Config();c.localTree=TREE;return c;}
 com.picviewer.core.Scanner.Result scan(LocalSource s,List<Photo> old,Set<String> dirs){return com.picviewer.core.Scanner.scan(s,"",old,dirs,new AtomicBoolean(false),null);}
 void drain()throws Exception{a.network.submit(()->{}).get(20,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 @Test public void recursiveTreeAndReadOnlyDecode()throws Exception{Config c=config();try(LocalSource s=new LocalSource(a,TREE)){com.picviewer.core.Scanner.Result r=scan(s,Collections.emptyList(),Collections.emptySet());assertTrue(r.complete());assertEquals(2,r.photos.size());assertTrue(r.folders.contains("여행"));Images images=new Images(a,c);try{for(Photo p:r.photos){Images.Decoded d=images.decode(p,960,600);assertNotNull(d.bitmap);d.bitmap.recycle();}}finally{images.close();}assertEquals(Arrays.asList("r","r"),provider.modes);}}
 @Test public void rejectsChangedMetadata()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){Photo p=scan(s,Collections.emptyList(),Collections.emptySet()).photos.get(0);Node n=provider.nodes.get(p.name().equals("사진2.png")?"png":"jpeg");n.modified++;try{s.fetch(p.path,new File(a.getCacheDir(),"out"),Images.MAX_FILE,p.size,p.modified);fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("FILE_CHANGED"));}}}
 @Test public void checksAfterRead()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){provider.mutate=true;try{s.fetch("사진2.png",new File(a.getCacheDir(),"out"),Images.MAX_FILE,-1,-1);fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("FILE_CHANGED"));}}}
 @Test public void unknownSizeStillHasByteLimit()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){provider.unknownSize=true;try{s.fetch("사진2.png",new File(a.getCacheDir(),"out"),8,-1,-1);fail();}catch(IOException expected){assertEquals("FILE_LIMIT",expected.getMessage());}}}
 @Test public void missingDocumentIsNotSilentlyLoaded()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){try{s.fetch("missing.jpg",new File(a.getCacheDir(),"out"),Images.MAX_FILE,-1,-1);fail();}catch(FileNotFoundException expected){}}}
 @Test public void nullListingPreservesSnapshot()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){com.picviewer.core.Scanner.Result before=scan(s,Collections.emptyList(),Collections.emptySet());provider.nullQuery=true;com.picviewer.core.Scanner.Result after=scan(s,before.photos,before.folders);assertFalse(after.complete());assertEquals(before.photos,after.photos);}}
 @Test public void loadingListingPreservesSnapshot()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){com.picviewer.core.Scanner.Result before=scan(s,Collections.emptyList(),Collections.emptySet());provider.loading=true;com.picviewer.core.Scanner.Result after=scan(s,before.photos,before.folders);assertFalse(after.complete());assertEquals(before.photos,after.photos);}}
 @Test public void revokedPermissionAbortsScan()throws Exception{provider.denied=true;try(LocalSource s=new LocalSource(a,TREE)){try{scan(s,Collections.emptyList(),Collections.emptySet());fail();}catch(com.picviewer.core.Scanner.Unavailable expected){}}}
 @Test public void additionsAndDeletionsRescan()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){com.picviewer.core.Scanner.Result before=scan(s,Collections.emptyList(),Collections.emptySet());provider.nodes.remove("jpeg");add("new","추가.jpg","folder");com.picviewer.core.Scanner.Result after=scan(s,before.photos,before.folders);assertEquals(2,after.photos.size());assertTrue(after.photos.stream().anyMatch(p->p.path.equals("여행/추가.jpg")));assertFalse(after.photos.stream().anyMatch(p->p.path.equals("여행/사진1.jpg")));}}
 @Test public void pickerRequestsReadOnlyLocalTree(){a.chooseLocalFolder();Intent i=Shadows.shadowOf(a).getNextStartedActivityForResult().intent;assertEquals(Intent.ACTION_OPEN_DOCUMENT_TREE,i.getAction());assertTrue(i.getBooleanExtra(Intent.EXTRA_LOCAL_ONLY,false));assertEquals(0,i.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION);assertTrue((i.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0);}
 @Test public void cancelledPickerKeepsSource(){String before=a.config.source();a.onActivityResult(MainActivity.PICK_LOCAL,MainActivity.RESULT_CANCELED,null);assertEquals(before,a.config.source());}
 @Test public void localConfigPersistsWithoutReplacingPcFields()throws Exception{a.getSharedPreferences("connection",0).edit().putString("host","saved-fixture").putString("user","reader").putString("share","photos").commit();Config c=config();c.save(a);assertTrue(Config.load(a).local());assertEquals(TREE,Config.load(a).localTree);assertEquals("saved-fixture",Config.loadSmb(a).host);assertEquals("",a.getSharedPreferences("connection",0).getString("secret",""));assertNotEquals(c.source(),Config.loadSmb(a).source());}
 @Test public void localGalleryPlaybackAndRevocationUi()throws Exception{a.activate(config());a.scan(true);drain();assertTrue(a.online);assertEquals(2,a.displayed.size());a.startPlayback("여행/사진1.jpg");a.decode.submit(()->{}).get(20,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();assertNotNull(a.shown);provider.denied=true;a.scan(false);drain();assertFalse(a.playing);assertEquals("LOCAL",a.failure);assertEquals(2,a.all.size());}
 @Test public void localSelectionAndScreenshot()throws Exception{a.activate(config());a.scan(true);drain();assertEquals(2,a.displayed.size());a.selection.set("여행",false);a.refreshSelection();assertEquals(1,a.displayed.size());a.selection.all("",true);a.refreshSelection();capture("local-gallery");}
 @Test public void sourceSwitchClearsOldQueueAndCache()throws Exception{a.startDemo();a.images.file(a.all.get(0));a.startPlayback(null);a.activate(config());assertNull(a.playlist);assertEquals(0,a.all.size());assertEquals(0,a.images.bytes());assertFalse(a.demo);assertTrue(a.config.local());}
 @Test public void pickerResultPersistsGrantAndLoadsLocal()throws Exception{Intent intent=new Intent();intent.setData(Uri.parse(TREE));intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);a.onActivityResult(MainActivity.PICK_LOCAL,MainActivity.RESULT_OK,intent);drain();assertTrue(a.config.local());assertEquals(2,a.all.size());assertTrue(a.getContentResolver().getPersistedUriPermissions().stream().anyMatch(p->p.getUri().toString().equals(TREE)&&p.isReadPermission()&&!p.isWritePermission()));}
 @Test public void localActivityRestartRestoresLocation()throws Exception{a.activate(config());a.scan(true);drain();a.onDestroy();a=Robolectric.buildActivity(MainActivity.class).setup().get();drain();assertTrue(a.config.local());assertEquals(2,a.displayed.size());}
 @Test public void duplicateNamesDoNotConfirmDeletion()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){com.picviewer.core.Scanner.Result before=scan(s,Collections.emptyList(),Collections.emptySet());add("duplicate","사진2.png","root");com.picviewer.core.Scanner.Result after=scan(s,before.photos,before.folders);assertFalse(after.complete());assertEquals(before.photos,after.photos);}}
 @Test public void providerErrorPreservesSnapshot()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){com.picviewer.core.Scanner.Result before=scan(s,Collections.emptyList(),Collections.emptySet());provider.error=true;com.picviewer.core.Scanner.Result after=scan(s,before.photos,before.folders);assertFalse(after.complete());assertEquals(before.photos,after.photos);}}
 @Test public void staleDocumentIdIsResolvedAgain()throws Exception{try(LocalSource s=new LocalSource(a,TREE)){File out=new File(a.getCacheDir(),"out");s.fetch("사진2.png",out,Images.MAX_FILE,-1,-1);provider.nodes.remove("png");add("replacement","사진2.png","root");s.fetch("사진2.png",out,Images.MAX_FILE,-1,-1);assertTrue(out.length()>0);}}
 @Test public void unknownMetadataGetsNewCacheVersionEachScan()throws Exception{provider.unknownSize=true;try(LocalSource s=new LocalSource(a,TREE)){Photo first=scan(s,Collections.emptyList(),Collections.emptySet()).photos.get(0);Photo second=scan(s,Collections.emptyList(),Collections.emptySet()).photos.get(0);assertTrue(first.modified<0);assertNotEquals(first.key(config().source()),second.key(config().source()));}}
 void capture(String name)throws Exception{android.view.View v=a.getWindow().getDecorView();v.measure(android.view.View.MeasureSpec.makeMeasureSpec(960,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(600,1073741824));v.layout(0,0,960,600);a.thumbs.submit(()->{}).get(20,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(960,600,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));File dir=new File(System.getProperty("picviewer.screenshots","build/screenshots"));dir.mkdirs();try(OutputStream o=new FileOutputStream(new File(dir,name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,o);}b.recycle();}
}
